@group(0) @binding(1) var input_sampler : sampler;

struct Params {
    time:                 f32,
    frost_intensity:      f32,
    chromatic_aberration: f32,
    blur_samples:         f32,
}
@group(0) @binding(2) var<uniform> params : Params;

struct FragInput {
    @builtin(position) pos : vec4f,
    @location(0)       uv  : vec2f,
}

// Pseudo-random noise for frost displacement
fn rand2(p: vec2f) -> vec2f {
    let k = vec2f(127.1, 311.7);
    let s = sin(dot(p, k)) * 43758.5453;
    return fract(vec2f(s, s * 1.3)) * 2.0 - 1.0;
}

@fragment
fn fs_main(in: FragInput) -> @location(0) vec4f {
    let frost    = params.frost_intensity;
    let chroma   = params.chromatic_aberration;
    let uv       = in.uv;

    // Frost displacement — jitter UV by noise scaled by intensity
    let jitter   = rand2(floor(uv * 80.0) / 80.0) * frost * 0.018;
    let uv_frost = uv + jitter;

    // Chromatic aberration — offset R and B channels in opposite directions
    let offset   = vec2f(chroma * 0.012, 0.0);
    let r = textureSampleLevel(input_texture, input_sampler, uv_frost + offset, 0.0).r;
    let g = textureSampleLevel(input_texture, input_sampler, uv_frost,          0.0).g;
    let b = textureSampleLevel(input_texture, input_sampler, uv_frost - offset, 0.0).b;

    return vec4f(r, g, b, 1.0);
}
