@group(0) @binding(0) var input_texture : texture_2d<f32>;
@group(0) @binding(1) var input_sampler : sampler;

struct Params {
    time:          f32,
    glitch_amount: f32,
    tear_frequency: f32,
}
@group(0) @binding(2) var<uniform> params : Params;

struct FragInput {
    @builtin(position) pos : vec4f,
    @location(0)       uv  : vec2f,
}

fn hash(n: f32) -> f32 {
    return fract(sin(n) * 43758.5453);
}

@fragment
fn fs_main(in: FragInput) -> @location(0) vec4f {
    var uv = in.uv;

    // Horizontal scanline tears — displace rows by a noise-based offset
    let row        = floor(uv.y * params.tear_frequency);
    let tear_seed  = hash(row + floor(params.time * 8.0) * 0.1);
    let tear_shift = (tear_seed - 0.5) * params.glitch_amount * 0.12;

    // Only apply tear to a subset of rows (threshold keeps effect sparse)
    if (tear_seed > 0.85) {
        uv.x = fract(uv.x + tear_shift);
    }

    // RGB split proportional to horizontal position and glitch amount
    let split = params.glitch_amount * 0.008;
    let r = textureSampleLevel(input_texture, input_sampler, uv + vec2f( split, 0.0), 0.0).r;
    let g = textureSampleLevel(input_texture, input_sampler, uv,                       0.0).g;
    let b = textureSampleLevel(input_texture, input_sampler, uv - vec2f( split, 0.0), 0.0).b;

    return vec4f(r, g, b, 1.0);
}
